// Prepara triagem: o nó Webhook embrulha o POST em
// { headers, params, query, body }. O agente precisa de `candidates` direto.
const item = $input.first().json;
const body = item.body ?? item;
return [{ candidates: Array.isArray(body.candidates) ? body.candidates : [] }];

// Formata top-5: garante { picks: [...] } mesmo com texto livre. 1) output.picks 2) output.state objeto ou JSON-string 3) fallback cities+tese (conf 50).
const item = $input.first().json;
const out = item.output ?? item;
let picks = null;
if (Array.isArray(out.picks)) picks = out.picks;
const st = out.state;
if (!picks && st && typeof st === 'object' && Array.isArray(st.picks)) picks = st.picks;
if (!picks && typeof st === 'string') {
  const t = st.trim().replace(/^```json\s*/i, '').replace(/\s*```$/, '');
  if (t.startsWith('{') || t.startsWith('[')) {
    try { const p = JSON.parse(t); picks = Array.isArray(p) ? p : (p.picks ?? null); } catch (e) {}
  }
}
if (!picks && Array.isArray(out.cities) && out.cities.length > 0) {
  const thesis = typeof st === 'string' ? st.slice(0, 500) : 'Selecao do agente (sem detalhe estruturado).';
  picks = out.cities.slice(0, 5).map((s) => ({ symbol: String(s).toUpperCase(), direction: 'UP', confidence: 50, thesis, catalysts: [], risks: ['Agente sem analise estruturada - rever com cautela'], invalidation: '' }));
}
if (!Array.isArray(picks)) picks = [];
picks = picks.slice(0, 5).map((p) => ({ symbol: String(p.symbol || '').toUpperCase(), direction: p.direction === 'DOWN' ? 'DOWN' : p.direction === 'NEUTRAL' ? 'NEUTRAL' : 'UP', confidence: Number.isFinite(Number(p.confidence)) ? Math.min(100, Math.max(0, Number(p.confidence))) : 50, thesis: typeof p.thesis === 'string' ? p.thesis.slice(0, 500) : '', catalysts: Array.isArray(p.catalysts) ? p.catalysts.map(String).slice(0, 5) : [], risks: Array.isArray(p.risks) ? p.risks.map(String).slice(0, 5) : [], invalidation: typeof p.invalidation === 'string' ? p.invalidation.slice(0, 300) : '' })).filter((p) => p.symbol);
return [{ picks }];
